import fs from "node:fs";
const dir = new URL("../shared/", import.meta.url);
const schema = JSON.parse(
  fs.readFileSync(
    new URL("role-view-config.schema.prototype.json", dir),
    "utf8",
  ),
);
fs.writeFileSync(
  new URL("role-view-schema.prototype.js", dir),
  "// Generated by checks/generate-presentation-schema.mjs from role-view-config.schema.prototype.json.\nwindow.RolePresentationSchema = " +
    JSON.stringify(schema, null, 2) +
    ";\n",
);
